// "The Ocean Has a Door" — make.fun ai-excited-01 entry.
// Copies the repo-held entry.png (the judged image) to the output dir.
// Node 22, standard library only. No network, no generated bytes.
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const MAX_BYTES = 1048576; // 1 MiB gate from RULES.txt
const MAX_DIM = 1024;

function fail(message) {
  console.error(`entry: ${message}`);
  process.exit(1);
}

// Locate the image shipped with this repo, next to this file.
const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, "entry.png");
if (!existsSync(source)) fail(`entry.png not found next to main.ts (${source})`);

const bytes = readFileSync(source);

// Gate 1: JPEG magic (FF D8 FF) and end marker (FF D9).
if (bytes.length < 4 || bytes[0] !== 0xff || bytes[1] !== 0xd8 || bytes[2] !== 0xff) {
  fail("entry.png is not a JPEG (bad magic bytes)");
}
if (bytes[bytes.length - 2] !== 0xff || bytes[bytes.length - 1] !== 0xd9) {
  fail("entry.png is truncated (missing JPEG end marker)");
}

// Gate 2: size cap.
if (bytes.length > MAX_BYTES) {
  fail(`entry.png is ${bytes.length} bytes, over the ${MAX_BYTES} byte cap`);
}

// Gate 3: dimensions, read by walking JPEG segments properly instead of
// scanning raw bytes (a naive scan can false-match on 0xFF bytes inside
// compressed scan data). Standalone markers (RSTn, SOI, TEM) carry no
// length field; every other segment is skipped by its declared length.
function jpegDimensions(buf) {
  let i = 2; // past SOI
  while (i + 1 < buf.length) {
    if (buf[i] !== 0xff) return null; // lost sync: not a well-formed JPEG
    let marker = buf[i + 1];
    // Skip fill bytes (0xFF padding between segments).
    while (marker === 0xff) {
      i += 1;
      marker = buf[i + 1];
    }
    if (marker === 0xd9) return null; // EOI reached without a frame
    if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
      i += 2; // standalone marker, no payload
      continue;
    }
    if (i + 4 > buf.length) return null;
    const length = (buf[i + 2] << 8) | buf[i + 3];
    if (length < 2 || i + length > buf.length) return null;
    // SOF0–SOF15 except DHT (C4), JPG (C8) and DAC (CC): 5 payload bytes
    // in, height then width, each 2 bytes big-endian.
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      if (length < 7) return null;
      const height = (buf[i + 5] << 8) | buf[i + 6];
      const width = (buf[i + 7] << 8) | buf[i + 8];
      return { width, height };
    }
    if (marker === 0xda) return null; // SOS: frame header must precede it
    i += 2 + length;
  }
  return null;
}
const dims = jpegDimensions(bytes);
if (!dims) fail("entry.png has no JPEG frame header");
if (dims.width > MAX_DIM || dims.height > MAX_DIM) {
  fail(`entry.png is ${dims.width}x${dims.height}, over the ${MAX_DIM}x${MAX_DIM} cap`);
}

const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output";
mkdirSync(outDir, { recursive: true });
const target = join(outDir, "entry.png");
writeFileSync(target, bytes);

// Verify: the output must be byte-identical to the source image.
const written = readFileSync(target);
const hash = (b) => createHash("sha256").update(b).digest("hex");
if (hash(written) !== hash(bytes)) fail("output differs from entry.png after write");
if (statSync(target).size !== bytes.length) fail("output size mismatch");

console.log(`entry: wrote ${target} (${dims.width}x${dims.height}, ${bytes.length} bytes, sha256 ${hash(bytes).slice(0, 16)}…)`);
